package com.easytasks.infoboxes;

import com.easytasks.tasks.TaskStep;
import com.easytasks.tasks.birdhouse.BirdhouseTask;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;

import java.awt.Color;
import java.awt.image.BufferedImage;

/**
 * Plan §6.2: Shows current step instruction and progress (Step X/Y: [Action]).
 */
public class StepGuidanceInfoBox extends InfoBox
{
	private final BirdhouseTask task;
	private final Client client;

	public StepGuidanceInfoBox(BufferedImage image, Plugin plugin, BirdhouseTask task, Client client)
	{
		super(image, plugin);
		this.task = task;
		this.client = client;
		setTooltip("Current step in birdhouse run");
	}

	@Override
	public String getText()
	{
		if (task == null || !task.isActive()) return "";
		TaskStep step = task.getCurrentStep();
		if (step == null) return "";
		WorldPoint playerWp = client.getLocalPlayer() != null ? client.getLocalPlayer().getWorldLocation() : null;
		int current = task.getCompletedSteps() + 1;
		int total = task.getTotalSteps();
		String instruction = task.getCurrentStepInstruction(playerWp);
		if (instruction == null) instruction = step.getDescription();
		return current + "/" + total + ": " + instruction;
	}

	@Override
	public Color getTextColor()
	{
		return Color.WHITE;
	}

	@Override
	public boolean render()
	{
		return task != null && task.isActive();
	}

	/** Called when task state changes (e.g. after varbit change). */
	public void update()
	{
		if (task == null) return;
		WorldPoint playerWp = client.getLocalPlayer() != null ? client.getLocalPlayer().getWorldLocation() : null;
		String instruction = task.getCurrentStepInstruction(playerWp);
		setTooltip(instruction != null ? instruction : "Progress: " + task.getProgress() + "%");
	}}

package com.easytasks.infoboxes;

import com.easytasks.tasks.Task;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.List;

/**
 * Tracks a single required item and auto-removes when gathered.
 * Multiple instances are created per task, one for each required item.
 * If the user drops items mid-run after gathering, infoboxes will reappear
 * (missing count updates from inventory); this is intentional.
 */
public class ItemTrackingInfoBox extends InfoBox
{
	private final Task task;
	private final Task.RequiredItem requiredItem;
	private final Client client;
	private final ItemManager itemManager;
	private int missingCount = 0;
	private String tooltipText = "";

	public ItemTrackingInfoBox(BufferedImage image, Plugin plugin, Task.RequiredItem requiredItem, Task task, Client client, ItemManager itemManager)
	{
		super(image, plugin);
		this.requiredItem = requiredItem;
		this.task = task;
		this.client = client;
		this.itemManager = itemManager;
		update();
	}

	/** Only the count still needed is shown on the infobox; no other text. */
	@Override
	public String getText()
	{
		if (missingCount > 0)
			return missingCount + "x";
		return "";
	}

	@Override
	public Color getTextColor()
	{
		return missingCount <= 0 ? Color.GREEN : Color.ORANGE;
	}

	@Override
	public boolean render()
	{
		return missingCount > 0 && task.isActive();
	}

	@Override
	public String getTooltip()
	{
		return tooltipText;
	}

	/** Called when inventory changes; recomputes missing count and tooltip for this item. */
	public void update()
	{
		if (task == null || !task.isActive())
		{
			missingCount = 0;
			tooltipText = "";
			return;
		}
		ItemContainer inv = client.getItemContainer(InventoryID.INVENTORY);
		int have = countItemsInList(inv, requiredItem.getItemIds());
		missingCount = Math.max(0, requiredItem.getQuantity() - have);
		String itemName = itemManager.getItemComposition(requiredItem.getItemId()).getName();
		if (missingCount > 0)
			tooltipText = "Need " + missingCount + " more " + itemName;
		else
			tooltipText = itemName + ": Ready";
		setTooltip(tooltipText);
	}

	private static int countItemsInList(ItemContainer container, List<Integer> itemIds)
	{
		if (container == null || itemIds == null) return 0;
		int count = 0;
		for (Item item : container.getItems())
			if (itemIds.contains(item.getId())) count += item.getQuantity();
		return count;
	}
}

package com.easytasks.ui;

import com.easytasks.BirdhouseConfig;
import com.easytasks.tasks.Task;
import com.easytasks.tasks.TaskManager;
import com.easytasks.tasks.birdhouse.BirdhouseTask;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.PluginPanel;

import javax.inject.Inject;
import javax.swing.*;
import java.awt.*;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.StringSelection;
import java.awt.datatransfer.Transferable;
import java.util.Optional;

public class BirdhouseSidePanel extends PluginPanel implements TaskManager.TaskStateListener
{
	private static final String[] LOCATION_NAMES = {"Verdant Valley (North)", "Verdant Valley (South)", "Mushroom Forest", "Tar Swamp"};

	private static final Color BG_DARK = new Color(0x2b2b2b);
	private static final Color BG_PANEL = new Color(0x1e1e1e);
	private static final Color FG_LIGHT = new Color(0xe0e0e0);
	private static final Color BUTTON_BG = new Color(0x1a1a1a);
	private static final Color BUTTON_FG = Color.WHITE;
	private static final Color PROGRESS_BG = new Color(0x333333);
	private static final Color PROGRESS_FG = new Color(0x4a9eff);

	private final BirdhouseConfig config;
	private final TaskManager taskManager;
	private final ConfigManager configManager;

	private final JButton startStopButton;
	private final JProgressBar progressBar;
	private final JLabel progressLabel;
	private final JList<Integer> routeList;
	private final DefaultListModel<Integer> routeModel;

	private Runnable onStartRequested;
	private Runnable onStopRequested;
	private Runnable onItemListRefreshRequested;

	@Inject
	public BirdhouseSidePanel(BirdhouseConfig config, TaskManager taskManager, ConfigManager configManager)
	{
		this.config = config;
		this.taskManager = taskManager;
		this.configManager = configManager;

		setLayout(new BorderLayout(0, 8));
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		setBackground(BG_DARK);

		JPanel header = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		header.setBackground(BG_DARK);
		JLabel title = new JLabel("Pick a birdhouse run:");
		title.setFont(title.getFont().deriveFont(Font.PLAIN, 13f));
		title.setForeground(FG_LIGHT);
		header.add(title);
		add(header, BorderLayout.NORTH);

		JPanel center = new JPanel();
		center.setLayout(new BoxLayout(center, BoxLayout.Y_AXIS));
		center.setBackground(BG_DARK);

		startStopButton = new JButton("Start Birdhouse Run");
		startStopButton.addActionListener(e -> toggleRun());
		styleButton(startStopButton);
		center.add(startStopButton);
		center.add(Box.createVerticalStrut(10));

		progressBar = new JProgressBar(0, 100);
		progressBar.setValue(0);
		progressBar.setPreferredSize(new Dimension(0, 14));
		progressBar.setBackground(PROGRESS_BG);
		progressBar.setForeground(PROGRESS_FG);
		center.add(progressBar);
		progressLabel = new JLabel("0/4 locations completed");
		progressLabel.setForeground(FG_LIGHT);
		progressLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		center.add(progressLabel);
		center.add(Box.createVerticalStrut(12));

		JLabel routeTitle = new JLabel("Route order (drag to reorder)");
		routeTitle.setForeground(FG_LIGHT);
		routeTitle.setAlignmentX(Component.LEFT_ALIGNMENT);
		center.add(routeTitle);
		center.add(Box.createVerticalStrut(4));
		routeModel = new DefaultListModel<>();
		routeList = new JList<>(routeModel);
		routeList.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
		routeList.setDragEnabled(true);
		routeList.setDropMode(DropMode.INSERT);
		routeList.setTransferHandler(new RouteOrderTransferHandler());
		routeList.setBackground(BG_PANEL);
		routeList.setForeground(FG_LIGHT);
		routeList.setSelectionBackground(new Color(0x404040));
		routeList.setSelectionForeground(FG_LIGHT);
		routeList.setCellRenderer((list, value, index, isSelected, cellHasFocus) -> {
			String display = getRouteDisplayName(value);
			JLabel l = new JLabel((index + 1) + ". " + display);
			l.setOpaque(true);
			l.setBackground(isSelected ? list.getSelectionBackground() : BG_PANEL);
			l.setForeground(isSelected ? list.getSelectionForeground() : FG_LIGHT);
			return l;
		});
		routeList.setVisibleRowCount(4);
		routeList.setPreferredSize(new Dimension(0, 80));
		JScrollPane routeScroll = new JScrollPane(routeList);
		routeScroll.setVerticalScrollBarPolicy(ScrollPaneConstants.VERTICAL_SCROLLBAR_NEVER);
		routeScroll.setBackground(BG_DARK);
		routeScroll.getViewport().setBackground(BG_PANEL);
		center.add(routeScroll);

		JScrollPane scroll = new JScrollPane(center);
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 0));
		scroll.getViewport().setBackground(BG_DARK);
		add(scroll, BorderLayout.CENTER);
	}

	@Override
	public void addNotify()
	{
		super.addNotify();
		taskManager.addTaskStateListener(this);
		refreshRouteOrderFromConfig();
	}

	@Override
	public void removeNotify()
	{
		taskManager.removeTaskStateListener(this);
		super.removeNotify();
	}

	private static void styleButton(JButton btn)
	{
		btn.setBackground(BUTTON_BG);
		btn.setForeground(BUTTON_FG);
		btn.setFocusPainted(false);
		btn.setBorder(BorderFactory.createLineBorder(new Color(0x444444)));
		btn.setPreferredSize(new Dimension(0, 28));
		btn.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
	}

	@SuppressWarnings("boxing")
	private static String getRouteDisplayName(Object value)
	{
		if (value == null || !(value instanceof Integer))
			return value == null ? "Unknown" : String.valueOf(value);
		int idx = (Integer) value;
		if (idx < 0 || idx >= LOCATION_NAMES.length)
			return "Unknown";
		return LOCATION_NAMES[idx];
	}

	private void toggleRun()
	{
		Optional<BirdhouseTask> existing = taskManager.getTaskByType(BirdhouseTask.class);
		if (existing.isPresent())
		{
			if (onStopRequested != null) onStopRequested.run();
		}
		else
		{
			if (onStartRequested != null) onStartRequested.run();
		}
	}

	public void setOnStartRequested(Runnable r) { onStartRequested = r; }
	public void setOnStopRequested(Runnable r) { onStopRequested = r; }
	public void setOnItemListRefreshRequested(Runnable r) { onItemListRefreshRequested = r; }

	/** Refreshes the item checklist (e.g. required-items infobox). Called when config changes. */
	public void refreshItemList()
	{
		if (onItemListRefreshRequested != null)
			onItemListRefreshRequested.run();
	}

	@Override
	public void onTaskRegistered(Task task)
	{
		SwingUtilities.invokeLater(() -> updateForTask(task));
	}

	@Override
	public void onTaskUnregistered(Task task)
	{
		SwingUtilities.invokeLater(this::updateIdle);
	}

	@Override
	public void onTaskStateChanged(Task task)
	{
		SwingUtilities.invokeLater(() -> updateForTask(task));
	}

	private void updateForTask(Task task)
	{
		if (!(task instanceof BirdhouseTask)) return;
		BirdhouseTask bt = (BirdhouseTask) task;
		startStopButton.setText("Stop Birdhouse Run");
		progressBar.setValue(bt.getProgress());
		progressLabel.setText(bt.getCompletedSteps() + "/" + bt.getTotalSteps() + " locations completed");
	}

	private void updateIdle()
	{
		startStopButton.setText("Start Birdhouse Run");
		progressBar.setValue(0);
		progressLabel.setText("0/4 locations completed");
	}

	/** Called when the run completes or stops so the button and progress reset. Safe to call from any thread. */
	public void setRunIdle()
	{
		SwingUtilities.invokeLater(this::updateIdle);
	}

	private void refreshRouteOrderFromConfig()
	{
		routeModel.clear();
		String order = configManager.getConfiguration("birdhouse", "routeOrder");
		if (order == null || order.isBlank()) order = "0,1,2,3";
		java.util.Set<Integer> added = new java.util.HashSet<>();
		for (String idxStr : order.split(","))
		{
			try
			{
				int i = Integer.parseInt(idxStr.trim());
				if (i >= 0 && i < 4 && added.add(i)) routeModel.addElement(i);
			}
			catch (NumberFormatException ignored) {}
		}
		for (int i = 0; i < 4; i++)
			if (!added.contains(i)) routeModel.addElement(i);
	}

	private void persistRouteOrder()
	{
		StringBuilder sb = new StringBuilder();
		for (int i = 0; i < routeModel.getSize(); i++)
		{
			if (i > 0) sb.append(",");
			sb.append(routeModel.get(i));
		}
		configManager.setConfiguration("birdhouse", "routeOrder", sb.toString());
	}

	/** Plan §4.1: Drag-and-drop reorder; persists routeOrder config immediately. */
	private class RouteOrderTransferHandler extends TransferHandler
	{
		private int sourceIndex = -1;

		@Override
		protected Transferable createTransferable(JComponent c)
		{
			if (!(c instanceof JList)) return null;
			@SuppressWarnings("unchecked")
			JList<Integer> list = (JList<Integer>) c;
			sourceIndex = list.getSelectedIndex();
			if (sourceIndex < 0 || sourceIndex >= routeModel.getSize()) return null;
			return new StringSelection(sourceIndex + ":" + routeModel.get(sourceIndex));
		}

		@Override
		public int getSourceActions(JComponent c) { return MOVE; }

		@Override
		public boolean canImport(TransferHandler.TransferSupport support)
		{
			if (!support.isDrop() || !support.isDataFlavorSupported(DataFlavor.stringFlavor)) return false;
			JList.DropLocation dl = (JList.DropLocation) support.getDropLocation();
			return dl.getIndex() >= 0 && dl.getIndex() <= routeModel.getSize();
		}

		@Override
		public boolean importData(TransferHandler.TransferSupport support)
		{
			if (!canImport(support)) return false;
			try
			{
				String data = (String) support.getTransferable().getTransferData(DataFlavor.stringFlavor);
				String[] parts = data.split(":");
				if (parts.length != 2) return false;
				int from = Integer.parseInt(parts[0]);
				int value = Integer.parseInt(parts[1]);
				int dropIndex = ((JList.DropLocation) support.getDropLocation()).getIndex();
				if (from == dropIndex || from == dropIndex - 1) return true;
				routeModel.remove(from);
				int insert = dropIndex > from ? dropIndex - 1 : dropIndex;
				routeModel.add(insert, value);
				persistRouteOrder();
				return true;
			}
			catch (Exception e) { return false; }
		}

		@Override
		protected void exportDone(JComponent source, Transferable data, int action)
		{
			sourceIndex = -1;
		}
	}

	public void refreshFromConfig() { SwingUtilities.invokeLater(this::refreshRouteOrderFromConfig); }

	/** Returns current route order (indices 0–3) for the task. Used when starting a run. */
	public int[] getRouteOrder()
	{
		int n = routeModel.getSize();
		int[] order = new int[4];
		for (int i = 0; i < 4 && i < n; i++)
			order[i] = routeModel.get(i);
		for (int i = n; i < 4; i++)
			order[i] = i;
		return order;
	}
}

package com.easytasks.tasks;

import net.runelite.api.coords.WorldPoint;

import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.List;

/**
 * Abstract contract for task management. Tasks represent a sequence of steps
 * (e.g., birdhouse run) with progress tracking and required items.
 */
public interface Task
{
	void start();
	void stop();
	boolean isActive();
	boolean isComplete();
	int getProgress();
	List<RequiredItem> getRequiredItems();
	List<? extends TaskLocation> getLocations();
	TaskStep getCurrentStep();
	int getCompletedSteps();
	int getTotalSteps();

	String getName();
	String getDescription();
	BufferedImage getIcon();

	interface RequiredItem
	{
		int getItemId();
		int getQuantity();
		/** IDs that satisfy this requirement (e.g. any birdhouse). Default: single getItemId(). */
		default List<Integer> getItemIds() { return Collections.singletonList(getItemId()); }
	}
}

package com.easytasks.tasks;

import net.runelite.api.coords.WorldPoint;

import java.util.List;

public class TaskLocation
{
	private final String name;
	private final WorldPoint worldPoint;
	private final List<Integer> objectIds;
	private final List<Integer> teleportObjectIds;
	private boolean visited;
	private boolean completed;

	public TaskLocation(String name, WorldPoint worldPoint, List<Integer> objectIds, List<Integer> teleportObjectIds)
	{
		this.name = name;
		this.worldPoint = worldPoint;
		this.objectIds = objectIds != null ? List.copyOf(objectIds) : List.of();
		this.teleportObjectIds = teleportObjectIds != null ? List.copyOf(teleportObjectIds) : List.of();
	}

	public String getName() { return name; }
	public WorldPoint getWorldPoint() { return worldPoint; }
	public List<Integer> getObjectIds() { return objectIds; }
	public List<Integer> getTeleportObjectIds() { return teleportObjectIds; }
	public boolean isVisited() { return visited; }
	public void setVisited(boolean visited) { this.visited = visited; }
	public boolean isCompleted() { return completed; }
	public void setCompleted(boolean completed) { this.completed = completed; }
}

package com.easytasks.tasks.birdhouse;

import com.easytasks.tasks.TaskLocation;
import net.runelite.api.Client;
import net.runelite.api.ObjectComposition;
import net.runelite.api.coords.WorldPoint;

import java.util.List;

public class BirdhouseLocation extends TaskLocation
{
	private final int patchObjectId;

	/** Previous varp value for this patch (to detect 19→21 = just filled). */
	private int lastVarplayerValue = -1;
	/** True when varp transitioned 19→21 this run (newly seeded); don't show "harvest" until they harvest. */
	private boolean filledThisRun;
	/** True when we've seen varp 19 at this location this step (needs filling); next varp 21 = just filled, advance. */
	private boolean hadNeedsFilling;

	public BirdhouseLocation(String name, WorldPoint worldPoint,
	                         List<Integer> objectIds, List<Integer> teleportObjectIds,
	                         int patchObjectId)
	{
		super(name, worldPoint, objectIds, teleportObjectIds);
		this.patchObjectId = patchObjectId;
	}

	/** Object ID for this patch (same whether empty or occupied; state from object definition). */
	public int getPatchObjectId() { return patchObjectId; }

	/** Read state value (0, 19, 21) from the patch object definition (VarPlayer or Varbit). */
	public int getStateValue(Client client)
	{
		ObjectComposition comp = client.getObjectDefinition(patchObjectId);
		if (comp == null) return -1;
		int varpId = comp.getVarPlayerId();
		if (varpId != -1) return client.getVarpValue(varpId);
		int varbitId = comp.getVarbitId();
		if (varbitId != -1) return client.getVarbitValue(varbitId);
		return -1;
	}

	public int getLastVarplayerValue() { return lastVarplayerValue; }
	public void setLastVarplayerValue(int lastVarplayerValue) { this.lastVarplayerValue = lastVarplayerValue; }
	public boolean isFilledThisRun() { return filledThisRun; }
	public void setFilledThisRun(boolean filledThisRun) { this.filledThisRun = filledThisRun; }
	public boolean isHadNeedsFilling() { return hadNeedsFilling; }
	public void setHadNeedsFilling(boolean hadNeedsFilling) { this.hadNeedsFilling = hadNeedsFilling; }

	public boolean isEmpty(Client client)
	{
		return getStateValue(client) == BirdhouseData.VARPLAYER_VALUE_UNOCCUPIED;
	}
	public boolean isPlaced(Client client)
	{
		return getStateValue(client) == BirdhouseData.VARPLAYER_VALUE_OCCUPIED_EMPTY;
	}
	public boolean isOccupied(Client client)
	{
		return getStateValue(client) == BirdhouseData.VARPLAYER_VALUE_OCCUPIED_FULL;
	}
}

package com.easytasks.tasks.birdhouse;

import com.easytasks.BirdhouseConfig;
import com.easytasks.tasks.Task;
import com.easytasks.tasks.TaskLocation;
import com.easytasks.tasks.TaskManager;
import com.easytasks.tasks.TaskStep;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import javax.inject.Inject;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class BirdhouseTask implements Task
{
	private final Client client;
	private final TaskManager taskManager;
	private final BirdhouseConfig config;

	private volatile boolean active;
	private BirdhouseMode mode;
	private int[] routeOrder;
	private List<BirdhouseLocation> locations;
	private List<TaskStep> steps;
	private int currentStepIndex;
	private Runnable onCompleteCallback;

	@Inject
	public BirdhouseTask(Client client, TaskManager taskManager, BirdhouseConfig config)
	{
		this.client = client;
		this.taskManager = taskManager;
		this.config = config;
		this.locations = createDefaultLocations();
		this.steps = new ArrayList<>();
		this.currentStepIndex = 0;
		this.routeOrder = new int[]{0, 1, 2, 3};
	}

	public void setMode(BirdhouseMode mode) { this.mode = mode; }

	public void setRouteOrder(int[] routeOrder)
	{
		if (routeOrder == null || routeOrder.length != 4) return;
		this.routeOrder = routeOrder.clone();
		rebuildStepsFromRoute();
	}

	public void setOnCompleteCallback(Runnable onCompleteCallback) { this.onCompleteCallback = onCompleteCallback; }

	/** Rebuilds the step list from current routeOrder and resets currentStepIndex to match completed count. */
	public void rebuildStepsFromRoute()
	{
		buildStepSequence();
		int completed = getCompletedSteps();
		currentStepIndex = Math.min(Math.max(0, completed), Math.max(0, steps.size() - 1));
		taskManager.notifyTaskStateChanged(this);
	}

	private static List<BirdhouseLocation> createDefaultLocations()
	{
		List<Integer> allTeleportIds = BirdhouseData.MUSHROOM_TELEPORT_OBJECT_IDS;
		List<BirdhouseLocation> list = new ArrayList<>();
		list.add(new BirdhouseLocation("Verdant Valley (North)", BirdhouseData.VERDANT_VALLEY_NORTH, Collections.singletonList(BirdhouseData.OBJECT_ID_VALLEY_NORTH), Collections.singletonList(allTeleportIds.get(0)), BirdhouseData.OBJECT_ID_VALLEY_NORTH));
		list.add(new BirdhouseLocation("Verdant Valley (South)", BirdhouseData.VERDANT_VALLEY_SOUTH, Collections.singletonList(BirdhouseData.OBJECT_ID_VALLEY_SOUTH), Collections.singletonList(allTeleportIds.get(1)), BirdhouseData.OBJECT_ID_VALLEY_SOUTH));
		list.add(new BirdhouseLocation("Mushroom Forest", BirdhouseData.MUSHROOM_FOREST, Collections.singletonList(BirdhouseData.OBJECT_ID_MUSHROOM_FOREST), Collections.singletonList(allTeleportIds.get(2)), BirdhouseData.OBJECT_ID_MUSHROOM_FOREST));
		list.add(new BirdhouseLocation("Tar Swamp", BirdhouseData.TAR_SWAMP, Collections.singletonList(BirdhouseData.OBJECT_ID_TAR_SWAMP), Collections.singletonList(allTeleportIds.get(3)), BirdhouseData.OBJECT_ID_TAR_SWAMP));
		return list;
	}

	@Override
	public void start()
	{
		active = true;
		if (mode == null) mode = BirdhouseMode.BIRDHOUSES;
		for (BirdhouseLocation loc : locations)
		{
			loc.setVisited(false);
			loc.setCompleted(false);
			loc.setFilledThisRun(false);
			loc.setHadNeedsFilling(false);
			loc.setLastVarplayerValue(loc.getStateValue(client));
		}
		buildStepSequence();
		currentStepIndex = 0;
		taskManager.notifyTaskStateChanged(this);
	}

	@Override
	public void stop()
	{
		active = false;
		steps.clear();
		currentStepIndex = 0;
		taskManager.notifyTaskStateChanged(this);
	}

	@Override
	public boolean isActive() { return active; }

	@Override
	public boolean isComplete()
	{
		if (!active || locations == null) return false;
		for (int i = 0; i < 4; i++)
		{
			BirdhouseLocation loc = getLocationByRouteIndex(i);
			if (loc == null || !loc.isVisited()) return false;
		}
		return true;
	}

	@Override
	public int getProgress()
	{
		int total = getTotalSteps();
		return total == 0 ? 0 : (getCompletedSteps() * 100) / total;
	}

	@Override
	public List<RequiredItem> getRequiredItems()
	{
		if (mode == null) return Collections.emptyList();
		return mode.getRequiredItems();
	}

	@Override
	public List<? extends TaskLocation> getLocations()
	{
		return locations == null ? Collections.emptyList() : locations;
	}

	public List<BirdhouseLocation> getLocationsInRouteOrder()
	{
		if (locations == null || routeOrder == null) return Collections.emptyList();
		List<BirdhouseLocation> ordered = new ArrayList<>(4);
		for (int i = 0; i < 4; i++)
		{
			int idx = routeOrder[i];
			if (idx >= 0 && idx < locations.size()) ordered.add(locations.get(idx));
		}
		return ordered;
	}

	@Override
	public TaskStep getCurrentStep()
	{
		if (steps == null || steps.isEmpty() || currentStepIndex < 0 || currentStepIndex >= steps.size()) return null;
		return steps.get(currentStepIndex);
	}

	@Override
	public int getCompletedSteps()
	{
		int count = 0;
		for (BirdhouseLocation loc : getLocationsInRouteOrder()) if (loc.isVisited()) count++;
		return count;
	}

	@Override
	public int getTotalSteps() { return 4; }

	@Override
	public String getName() { return "Birdhouse Run"; }

	@Override
	public String getDescription() { return "Assists with birdhouse runs on Fossil Island."; }

	@Override
	public BufferedImage getIcon() { return null; }

	public BirdhouseMode getMode() { return mode; }
	public int[] getRouteOrder() { return routeOrder == null ? new int[]{0, 1, 2, 3} : routeOrder.clone(); }

	/** The location for the current step (by route order). */
	public BirdhouseLocation getCurrentStepLocation()
	{
		return getLocationByRouteIndex(currentStepIndex);
	}

	/** True when the current step is to use seeds on the birdhouse (occupied but empty). */
	public boolean isCurrentStepFillWithSeeds()
	{
		BirdhouseLocation loc = getCurrentStepLocation();
		return loc != null && loc.getStateValue(client) == BirdhouseData.VARPLAYER_VALUE_OCCUPIED_EMPTY;
	}

	/**
	 * Returns the instruction for the current step. If the player is not near the current step's patch,
	 * returns "Go to &lt;location&gt;". Otherwise uses the patch state (varp) at that location:
	 * 21 = harvest, 0 = build, 19 = fill. When just filled (varp 21 + hadNeedsFilling), returns next step's instruction.
	 */
	public String getCurrentStepInstruction(WorldPoint playerWp)
	{
		if (!active || locations == null) return null;
		return getInstructionForStep(currentStepIndex, playerWp);
	}

	/** 1-based step number for display; matches the instruction (e.g. 2 when showing "Go to" next location after completing first). */
	public int getCurrentStepNumberForDisplay(WorldPoint playerWp)
	{
		if (!active || locations == null) return 1;
		BirdhouseLocation loc = getLocationByRouteIndex(currentStepIndex);
		if (loc == null) return currentStepIndex + 1;
		boolean showingNext = false;
		if (playerWp != null && !isWithinProximity(playerWp, loc.getWorldPoint()))
		{
			boolean completed = loc.isVisited();
			if (!completed)
			{
				int varp = loc.getStateValue(client);
				if (varp == BirdhouseData.VARPLAYER_VALUE_OCCUPIED_FULL
					&& (loc.isFilledThisRun() || loc.isHadNeedsFilling()))
					completed = true;
			}
			if (completed) showingNext = true;
		}
		else if (loc.getStateValue(client) == BirdhouseData.VARPLAYER_VALUE_OCCUPIED_FULL
			&& (loc.isFilledThisRun() || loc.isHadNeedsFilling()))
			showingNext = true;
		int oneBased = showingNext ? currentStepIndex + 2 : currentStepIndex + 1;
		return Math.min(oneBased, getTotalSteps());
	}

	private String getInstructionForStep(int routeIndex, WorldPoint playerWp)
	{
		final int maxIndex = getLocationsInRouteOrder().size();
		if (routeIndex < 0 || routeIndex >= maxIndex) return null;

		while (routeIndex < maxIndex)
		{
			// On first step, only show "Gather the required items" when not yet at the first location.
			// Once at the first location (e.g. after building), show normal step instruction (fill seeds, etc.).
			if (routeIndex == 0 && !hasRequiredItems())
			{
				BirdhouseLocation first = getLocationByRouteIndex(0);
				if (first != null && (playerWp == null || !isWithinProximity(playerWp, first.getWorldPoint())))
					return "Gather the required items";
			}
			BirdhouseLocation loc = getLocationByRouteIndex(routeIndex);
			if (loc == null) return null;
			if (playerWp != null && !isWithinProximity(playerWp, loc.getWorldPoint()))
			{
				boolean completed = loc.isVisited();
				if (!completed)
				{
					int varp = loc.getStateValue(client);
					if (varp == BirdhouseData.VARPLAYER_VALUE_OCCUPIED_FULL
						&& (loc.isFilledThisRun() || loc.isHadNeedsFilling()))
						completed = true;
				}
				if (completed)
				{
					routeIndex++;
					continue;
				}
				return "Go to " + loc.getName();
			}
			int varp = loc.getStateValue(client);
			if (varp == BirdhouseData.VARPLAYER_VALUE_OCCUPIED_FULL)
			{
				if (loc.isFilledThisRun() || loc.isHadNeedsFilling())
				{
					routeIndex++;
					continue;
				}
				return "Empty the birdhouse to harvest it";
			}
			if (varp == BirdhouseData.VARPLAYER_VALUE_UNOCCUPIED)
				return "Click the patch to build a new birdhouse";
			if (varp == BirdhouseData.VARPLAYER_VALUE_OCCUPIED_EMPTY)
			{
				loc.setHadNeedsFilling(true);
				return "Click seeds, then click the birdhouse to fill it";
			}
			return "Visit " + loc.getName();
		}
		return null;
	}

	/** True if the player's inventory satisfies all required items for this task. */
	private boolean hasRequiredItems()
	{
		ItemContainer inv = client.getItemContainer(InventoryID.INVENTORY);
		if (inv == null) return false;
		for (RequiredItem ri : getRequiredItems())
		{
			int have = countItemsInContainer(inv, ri.getItemIds());
			if (have < ri.getQuantity()) return false;
		}
		return true;
	}

	private static int countItemsInContainer(ItemContainer container, List<Integer> itemIds)
	{
		if (container == null || itemIds == null) return 0;
		int count = 0;
		for (Item item : container.getItems())
			if (itemIds.contains(item.getId())) count += item.getQuantity();
		return count;
	}

	private boolean isWithinProximity(WorldPoint playerWp, WorldPoint locWp)
	{
		if (playerWp.getPlane() != locWp.getPlane()) return false;
		int dx = Math.abs(playerWp.getX() - locWp.getX());
		int dy = Math.abs(playerWp.getY() - locWp.getY());
		return Math.max(dx, dy) <= PROXIMITY_TILES;
	}

	private BirdhouseLocation getLocationByRouteIndex(int routeIndex)
	{
		List<BirdhouseLocation> ordered = getLocationsInRouteOrder();
		if (routeIndex < 0 || routeIndex >= ordered.size()) return null;
		return ordered.get(routeIndex);
	}

	private void buildStepSequence()
	{
		steps.clear();
		for (BirdhouseLocation loc : getLocationsInRouteOrder())
			steps.add(new TaskStep("Visit " + loc.getName(), loc.getWorldPoint(), Collections.emptyList(), () -> loc.isVisited()));
	}

	/** Plan §7.3: Detect Take (harvest), Build (place birdhouse). Advance on Fill is detected by polling state in checkProximityAndAdvance. */
	public void onMenuOptionClicked(String option, int objectId, int param0, int param1)
	{
		if (!active || locations == null) return;
		boolean take = "Take".equals(option);
		boolean build = "Build".equals(option);
		if (!take && !build) return;
		LocalPoint lp = LocalPoint.fromScene(param0, param1);
		if (lp == null) return;
		WorldPoint wp = WorldPoint.fromLocal(client, lp);
		for (BirdhouseLocation loc : locations)
		{
			if (loc.getPatchObjectId() == objectId && loc.getWorldPoint().equals(wp))
			{
				if (take)
				{
					loc.setFilledThisRun(false);
					loc.setHadNeedsFilling(false);
				}
				taskManager.notifyTaskStateChanged(this);
				break;
			}
		}
	}

	private void advanceToNextStep()
	{
		int completed = getCompletedSteps();
		if (completed < steps.size()) currentStepIndex = completed;
	}

	/** When the player is within this many tiles of the current patch, "Go to X" is suppressed and step instruction is shown. */
	private static final int PROXIMITY_TILES = 10;

	/**
	 * Polls state from object definition (VarPlayer/Varbit per patch). When current step's location
	 * has state 21 and hadNeedsFilling (or prev 19), mark filled and advance. Called every GameTick.
	 */
	public void checkProximityAndAdvance()
	{
		if (!active || locations == null) return;
		List<BirdhouseLocation> ordered = getLocationsInRouteOrder();
		if (currentStepIndex < 0 || currentStepIndex >= ordered.size()) return;
		BirdhouseLocation loc = ordered.get(currentStepIndex);
		if (loc.isVisited()) return;
		int value = loc.getStateValue(client);
		loc.setLastVarplayerValue(value);
		if (value == BirdhouseData.VARPLAYER_VALUE_OCCUPIED_EMPTY)
			loc.setHadNeedsFilling(true);
		else if (value == BirdhouseData.VARPLAYER_VALUE_OCCUPIED_FULL && loc.isHadNeedsFilling())
		{
			loc.setHadNeedsFilling(false);
			loc.setFilledThisRun(true);
			loc.setVisited(true);
			loc.setCompleted(true);
			advanceToNextStep();
			taskManager.notifyTaskStateChanged(this);
			if (isComplete())
			{
				if (onCompleteCallback != null)
				{
					onCompleteCallback.run();
					return;
				}
			}
		}
		else if (value != BirdhouseData.VARPLAYER_VALUE_OCCUPIED_FULL)
		{
			loc.setFilledThisRun(false);
			loc.setHadNeedsFilling(false);
		}
		// Ensure run auto-stops when all locations are completed (fallback if last step didn't fire callback)
		if (isComplete() && onCompleteCallback != null)
		{
			onCompleteCallback.run();
		}
	}
}

package com.easytasks.tasks.birdhouse;

import net.runelite.api.Client;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.coords.WorldPoint;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;

/**
 * Static game data for birdhouse runs. Plan §2.4, §9.
 *
 * Each birdhouse patch has a unique object ID and a unique VarPlayer for state.
 * VarPlayer value: 0 = unoccupied, 19 = occupied but empty, 21 = occupied and full (harvestable).
 */
public final class BirdhouseData
{
	private BirdhouseData() {}

	public static final List<Integer> SEED_IDS = Collections.unmodifiableList(Arrays.asList(
		ItemID.BARLEY_SEED, ItemID.HAMMERSTONE_HOP_SEED, ItemID.JUTE_SEED,
		ItemID.YANILLIAN_HOP_SEED, ItemID.KRANDORIAN_HOP_SEED, ItemID.WILDBLOOD_HOP_SEED
	));

	public static final List<Integer> BIRDHOUSE_IDS = Collections.unmodifiableList(Arrays.asList(
		ItemID.BIRDHOUSE_NORMAL, ItemID.BIRDHOUSE_OAK, ItemID.BIRDHOUSE_WILLOW, ItemID.BIRDHOUSE_TEAK,
		ItemID.BIRDHOUSE_MAPLE, ItemID.BIRDHOUSE_MAHOGANY, ItemID.BIRDHOUSE_YEW,
		ItemID.BIRDHOUSE_MAGIC, ItemID.BIRDHOUSE_REDWOOD
	));

	public static final List<Integer> LOG_IDS = Collections.unmodifiableList(Arrays.asList(
		ItemID.LOGS, ItemID.OAK_LOGS, ItemID.WILLOW_LOGS, ItemID.TEAK_LOGS,
		ItemID.MAPLE_LOGS, ItemID.MAHOGANY_LOGS, ItemID.YEW_LOGS,
		ItemID.MAGIC_LOGS, ItemID.REDWOOD_LOGS
	));

	/** Item ID for Clockwork (used when building birdhouses from logs). */
	public static final int CLOCKWORK_ITEM_ID = 8792;

	/** Resolves tier index to birdhouse item ID; returns Oak (index 1) if out of range. */
	public static int getBirdhouseId(int tierIndex)
	{
		if (tierIndex < 0 || tierIndex >= BIRDHOUSE_IDS.size()) return BIRDHOUSE_IDS.get(1);
		return BIRDHOUSE_IDS.get(tierIndex);
	}

	/** Resolves tier index to log item ID; returns Oak logs (index 1) if out of range. */
	public static int getLogId(int tierIndex)
	{
		if (tierIndex < 0 || tierIndex >= LOG_IDS.size()) return LOG_IDS.get(1);
		return LOG_IDS.get(tierIndex);
	}

	/** Resolves seed index to seed item ID; returns Barley (index 0) if out of range. */
	public static int getSeedId(int seedIndex)
	{
		if (seedIndex < 0 || seedIndex >= SEED_IDS.size()) return SEED_IDS.get(0);
		return SEED_IDS.get(seedIndex);
	}

	public static final List<Integer> MUSHROOM_TELEPORT_OBJECT_IDS = Collections.unmodifiableList(Arrays.asList(30922, 30923, 30924, 30925));

	/** Mushroom tree object (30924) in Mushroom Forest — highlight when next step is Verdant Valley so player uses it to get there. */
	public static final int MUSHROOM_TREE_TO_VALLEY_OBJECT_ID = 30924;

	/** Object ID per patch (unique per location). Order: valley north, valley south, forest, swamp. */
	public static final int OBJECT_ID_VALLEY_NORTH = 30567;
	public static final int OBJECT_ID_VALLEY_SOUTH = 30568;
	public static final int OBJECT_ID_MUSHROOM_FOREST = 30565;
	public static final int OBJECT_ID_TAR_SWAMP = 30566;

	/** VarPlayer value: unoccupied. */
	public static final int VARPLAYER_VALUE_UNOCCUPIED = 0;
	/** VarPlayer value: occupied but empty (no seeds). */
	public static final int VARPLAYER_VALUE_OCCUPIED_EMPTY = 19;
	/** VarPlayer value: occupied and full of seeds (harvestable). */
	public static final int VARPLAYER_VALUE_OCCUPIED_FULL = 21;

	public static final WorldPoint VERDANT_VALLEY_NORTH = new WorldPoint(3768, 3761, 0);
	public static final WorldPoint VERDANT_VALLEY_SOUTH = new WorldPoint(3763, 3755, 0);
	public static final WorldPoint MUSHROOM_FOREST = new WorldPoint(3677, 3882, 0);
	public static final WorldPoint TAR_SWAMP = new WorldPoint(3679, 3815, 0);

	/** Plan §5.3: Only render overlays when player is on Fossil Island (approximate bounding box). */
	public static boolean isOnFossilIsland(Client client)
	{
		if (client == null || client.getLocalPlayer() == null) return false;
		WorldPoint wp = client.getLocalPlayer().getWorldLocation();
		return wp.getX() >= 3600 && wp.getX() <= 3900
			&& wp.getY() >= 3700 && wp.getY() <= 3900
			&& wp.getPlane() == 0;
	}
}

package com.easytasks.tasks.birdhouse;

import com.easytasks.tasks.Task;
import net.runelite.api.gameval.ItemID;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public enum BirdhouseMode
{
	BIRDHOUSES,
	LOGS;

	/**
	 * Builds the required item list for this mode.
	 * BIRDHOUSES: any birdhouse (4), any valid seed (40), hammer, chisel.
	 * LOGS: any log (4), any valid seed (40), hammer, chisel.
	 */
	public List<Task.RequiredItem> getRequiredItems()
	{
		List<Task.RequiredItem> items = new ArrayList<>();
		if (this == BIRDHOUSES)
			items.add(new RequiredItemImpl(BirdhouseData.BIRDHOUSE_IDS, 4));
		else
			items.add(new RequiredItemImpl(BirdhouseData.LOG_IDS, 4));
		items.add(new RequiredItemImpl(BirdhouseData.SEED_IDS, 40));
		items.add(new RequiredItemImpl(ItemID.HAMMER, 1));
		items.add(new RequiredItemImpl(ItemID.CHISEL, 1));
		return Collections.unmodifiableList(items);
	}

	private static final class RequiredItemImpl implements Task.RequiredItem
	{
		private final List<Integer> itemIds;
		private final int quantity;
		RequiredItemImpl(int itemId, int quantity) { this.itemIds = Collections.singletonList(itemId); this.quantity = quantity; }
		RequiredItemImpl(List<Integer> itemIds, int quantity) { this.itemIds = List.copyOf(itemIds); this.quantity = quantity; }
		@Override public int getItemId() { return itemIds.get(0); }
		@Override public int getQuantity() { return quantity; }
		@Override public List<Integer> getItemIds() { return itemIds; }
	}
}

package com.easytasks.tasks;

import com.google.inject.Singleton;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Optional;
import java.util.concurrent.CopyOnWriteArrayList;

@Singleton
public class TaskManager
{
	private static final Logger log = LoggerFactory.getLogger(TaskManager.class);
	private final List<Task> activeTasks = new CopyOnWriteArrayList<>();
	private final List<TaskStateListener> listeners = new CopyOnWriteArrayList<>();

	public void registerTask(Task task)
	{
		if (task == null) return;
		try
		{
			activeTasks.add(task);
			task.start();
			notifyTaskRegistered(task);
		}
		catch (Exception e) { log.warn("Failed to register task", e); }
	}

	public void unregisterTask(Task task)
	{
		if (task == null) return;
		try
		{
			activeTasks.remove(task);
			task.stop();
			notifyTaskUnregistered(task);
		}
		catch (Exception e) { 
			log.warn("Failed to unregister task", e); }
	}

	public List<Task> getActiveTasks()
	{
		return Collections.unmodifiableList(new ArrayList<>(activeTasks));
	}

	@SuppressWarnings("unchecked")
	public <T extends Task> Optional<T> getTaskByType(Class<T> type)
	{
		return activeTasks.stream()
			.filter(type::isInstance)
			.map(t -> (T) t)
			.findFirst();
	}

	public void addTaskStateListener(TaskStateListener listener)
	{
		if (listener != null) listeners.add(listener);
	}

	public void removeTaskStateListener(TaskStateListener listener)
	{
		listeners.remove(listener);
	}

	private void notifyTaskRegistered(Task task)
	{
		for (TaskStateListener l : listeners)
		{
			try { l.onTaskRegistered(task); }
			catch (Exception e) { log.warn("TaskStateListener error", e); }
		}
	}

	private void notifyTaskUnregistered(Task task)
	{
		for (TaskStateListener l : listeners)
		{
			try { l.onTaskUnregistered(task); }
			catch (Exception e) { log.warn("TaskStateListener error", e); }
		}
	}

	public void notifyTaskStateChanged(Task task)
	{
		for (TaskStateListener l : listeners)
		{
			try { l.onTaskStateChanged(task); }
			catch (Exception e) { log.warn("TaskStateListener error", e); }
		}
	}

	public interface TaskStateListener
	{
		default void onTaskRegistered(Task task) {}
		default void onTaskUnregistered(Task task) {}
		default void onTaskStateChanged(Task task) {}
	}
}

package com.easytasks.tasks;

import net.runelite.api.coords.WorldPoint;

import java.util.List;
import java.util.function.BooleanSupplier;

public final class TaskStep
{
	private final String description;
	private final WorldPoint location;
	private final List<Integer> requiredItems;
	private final BooleanSupplier completionCondition;

	public TaskStep(String description, WorldPoint location, List<Integer> requiredItems, BooleanSupplier completionCondition)
	{
		this.description = description;
		this.location = location;
		this.requiredItems = requiredItems != null ? List.copyOf(requiredItems) : List.of();
		this.completionCondition = completionCondition != null ? completionCondition : () -> false;
	}

	public String getDescription() { return description; }
	public WorldPoint getLocation() { return location; }
	public List<Integer> getRequiredItems() { return requiredItems; }
	public boolean isComplete() { return completionCondition.getAsBoolean(); }
}

package com.easytasks.overlays;

import com.easytasks.BirdhouseConfig;
import com.easytasks.tasks.TaskManager;
import com.easytasks.tasks.birdhouse.BirdhouseData;
import com.easytasks.tasks.birdhouse.BirdhouseLocation;
import com.easytasks.tasks.birdhouse.BirdhouseTask;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.TileObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

import javax.inject.Inject;
import java.awt.*;
import java.util.Optional;

public class BirdhouseHighlightOverlay extends Overlay
{
	private final Client client;
	private final BirdhouseConfig config;
	private final TaskManager taskManager;

	@Inject
	public BirdhouseHighlightOverlay(Client client, BirdhouseConfig config, TaskManager taskManager)
	{
		this.client = client;
		this.config = config;
		this.taskManager = taskManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.highlightBirdhouses()) return null;
		if (!BirdhouseData.isOnFossilIsland(client)) return null;
		Optional<BirdhouseTask> opt = taskManager.getTaskByType(BirdhouseTask.class);
		if (opt.isEmpty()) return null;
		BirdhouseTask task = opt.get();
		if (!task.isActive()) return null;
		net.runelite.api.Scene scene = client.getScene();
		int plane = client.getPlane();
		BirdhouseLocation currentStepLoc = task.getCurrentStepLocation();
		boolean fillWithSeeds = task.isCurrentStepFillWithSeeds();
		for (BirdhouseLocation loc : task.getLocationsInRouteOrder())
		{
			if (loc.isVisited()) continue;
			Color color;
			if (fillWithSeeds && loc == currentStepLoc)
				color = Color.PINK;
			else if (loc.isEmpty(client)) color = config.emptySlotColor();
			else if (loc.isPlaced(client)) color = config.emptyBirdhouseColor();
			else if (loc.isOccupied(client)) color = config.occupiedBirdhouseColor();
			else color = config.emptySlotColor();
			WorldPoint wp = loc.getWorldPoint();
			LocalPoint localPoint = LocalPoint.fromWorld(client, wp);
			if (localPoint == null) continue;
			Shape hull = null;
			net.runelite.api.Tile tile = scene.getTiles()[plane][localPoint.getSceneX()][localPoint.getSceneY()];
			if (tile != null)
			{
				for (TileObject obj : tile.getGameObjects())
				{
					if (obj == null) continue;
					Shape box = obj.getClickbox();
					if (box != null)
					{
						hull = box;
						break;
					}
				}
			}
			if (hull == null)
				hull = Perspective.getCanvasTilePoly(client, localPoint);
			if (hull != null)
				OverlayUtil.renderPolygon(graphics, hull, color, new BasicStroke(config.highlightThickness()));
		}
		return null;
	}
}

